    res := res || jsonb_build_object('what', 'rate a game (whole star)', 'ok', coalesce(((bgc.rate('check.member@example.invalid', (SELECT s.legacy_id FROM shelves s JOIN games g ON g.id = s.game_id WHERE g.bgg_id = 999901 AND s.member_id = bgc.member_id('check.member@example.invalid')), 3) ->> 'ok')::boolean), false));
    res := res || jsonb_build_object('what', 'and again, in halves', 'ok', coalesce(((bgc.rate('check.member@example.invalid', (SELECT s.legacy_id FROM shelves s JOIN games g ON g.id = s.game_id WHERE g.bgg_id = 999901 AND s.member_id = bgc.member_id('check.member@example.invalid')), 3.5) ->> 'stars')::numeric = 3.5), false));
