    res := res || jsonb_build_object('what', 'signing in again picks them up', 'ok', coalesce(((bgc.bgg_link_save('check.member@example.invalid', 'check_bgg_user', 'v1.sealed2', NULL) -> 'link' ->> 'state') = 'ok'), false));
    res := res || jsonb_build_object('what', 'a second play, logged here', 'ok', coalesce(((bgc.log_play('check.member@example.invalid', (SELECT s.legacy_id FROM shelves s JOIN games g ON g.id = s.game_id WHERE g.bgg_id = 999901 AND s.member_id = bgc.member_id('check.member@example.invalid')), '{"date": "2026-10-21", "players": [{"name": "Check Member"}]}') ->> 'ok')::boolean), false));
    res := res || jsonb_build_object('what', 'the same play arrives from BGG', 'ok', coalesce(((at.save_plays('check.member@example.invalid', '[{"id": 987654322, "date": "2026-10-21", "bggId": 999901, "gameName": "Check BGG Game", "quantity": 1, "players": [{"seat": 1, "name": "check member"}]}]') ->> 'newPlays')::int = 1), false));
    res := res || jsonb_build_object('what', 'a play logged here and on BGG becomes one', 'ok', coalesce((bgc.merge_site_plays('check.member@example.invalid') = 1), false));
    res := res || jsonb_build_object('what', 'and isn''t sent to BGG a second time', 'ok', coalesce(((SELECT count(*) FROM plays WHERE owner_id = bgc.member_id('check.member@example.invalid') AND played_on = '2026-10-21') = 1
  AND NOT EXISTS (SELECT 1 FROM bgg_outbox WHERE member_id = bgc.member_id('check.member@example.invalid') AND kind = 'play' AND state = 'pending')), false));
    res := res || jsonb_build_object('what', 'a play posted from here isn''t its own duplicate', 'ok', coalesce((bgc.merge_site_plays('check.member@example.invalid') = 0), false));
    UPDATE bgg_outbox SET state = 'done' WHERE member_id = bgc.member_id('check.member@example.invalid') AND state = 'pending';
    res := res || jsonb_build_object('what', 'a BGG rating for the game', 'ok', coalesce((bgc.bgg_ratings_save('check_bgg_user', '[{"bggId": 999901, "rating10": 8.6}]') = 1), false));
    res := res || jsonb_build_object('what', 'BGG ratings fill in a linked member''s stars', 'ok', coalesce((bgc.stars_from_bgg('check_bgg_user') >= 1), false));
    res := res || jsonb_build_object('what', 'a BGG rating of 8.6 is 4.5 stars', 'ok', coalesce(((SELECT stars FROM ratings WHERE member_id = bgc.member_id('check.member@example.invalid') AND game_id = (SELECT id FROM games WHERE bgg_id = 999901)) = 4.5), false));
    res := res || jsonb_build_object('what', 'stars that came from BGG aren''t sent back to it', 'ok', coalesce((NOT EXISTS (SELECT 1 FROM bgg_outbox WHERE member_id = bgc.member_id('check.member@example.invalid') AND state = 'pending')), false));
    res := res || jsonb_build_object('what', 'remove the game', 'ok', coalesce(((bgc.shelf_remove('check.member@example.invalid', (SELECT s.legacy_id FROM shelves s JOIN games g ON g.id = s.game_id WHERE g.bgg_id = 999901 AND s.member_id = bgc.member_id('check.member@example.invalid'))) ->> 'ok')::boolean), false));
    res := res || jsonb_build_object('what', 'removing a game from the shelf takes it out of what you own on BGG', 'ok', coalesce(((SELECT want ->> 'own' FROM bgg_outbox WHERE member_id = bgc.member_id('check.member@example.invalid') AND state = 'pending') = 'false'), false));
    res := res || jsonb_build_object('what', 'a play of a game you don''t own', 'ok', coalesce(((bgc.log_play('check.member@example.invalid', NULL, '{"bggId": 999902, "title": "Check Friend Game", "date": "2026-10-22", "location": " Check Cafe ", "players": [{"name": "Check Member"}]}') ->> 'ok')::boolean), false));
    res := res || jsonb_build_object('what', 'is kept without putting the game on your shelf', 'ok', coalesce(((SELECT count(*) FROM plays WHERE owner_id = bgc.member_id('check.member@example.invalid') AND bgg_id = 999902) = 1
  AND NOT EXISTS (SELECT 1 FROM shelves s JOIN games g ON g.id = s.game_id WHERE g.bgg_id = 999902)), false));
    res := res || jsonb_build_object('what', 'your plays, newest first', 'ok', coalesce((bgc.my_plays('check.member@example.invalid', 0, 50) -> 'plays' -> 0 ->> 'title' = 'Check Friend Game'), false));
