    UPDATE play_players SET color = 'Blue', start_position = '2' WHERE name = 'Check Jo';
    res := res || jsonb_build_object('what', 'merge Check Jo into Check Joan', 'ok', coalesce(((bgc.person_merge('check.member@example.invalid', (SELECT legacy_id FROM players WHERE owner_id = bgc.member_id('check.member@example.invalid') AND name = 'Check Jo'),
  (SELECT legacy_id FROM players WHERE owner_id = bgc.member_id('check.member@example.invalid') AND name = 'Check Joan')) ->> 'ok')::boolean), false));
