  AND (SELECT aliases FROM players WHERE owner_id = bgc.member_id('check.member@example.invalid') AND name = 'Check Joan') = ARRAY['Check Jo']), false));
    res := res || jsonb_build_object('what', 'her play moved over, color and all', 'ok', coalesce(((SELECT string_agg(pp.name || '/' || pp.color, ',') FROM play_players pp JOIN plays p ON p.id = pp.play_id WHERE p.owner_id = bgc.member_id('check.member@example.invalid') AND p.played_on = '2026-10-17') = 'Check Joan/Blue'), false));
    res := res || jsonb_build_object('what', 'you can''t be merged into someone else', 'ok', coalesce((NOT (bgc.person_merge('check.member@example.invalid', (SELECT legacy_id FROM players WHERE owner_id = bgc.member_id('check.member@example.invalid') AND linked_member_id = bgc.member_id('check.member@example.invalid')),
