    UPDATE plays SET location = 'Check Caf' WHERE owner_id = bgc.member_id('check.member@example.invalid') AND played_on = '2026-10-17';
    res := res || jsonb_build_object('what', 'a play synced from BGG under the old name moves too', 'ok', coalesce((bgc.apply_place_aliases('check.member@example.invalid') = 1), false));
