    res := res || jsonb_build_object('what', 'with its people and winner', 'ok', coalesce(((SELECT string_agg(pp.name || ':' || pp.win, ',' ORDER BY pp.seat) FROM play_players pp JOIN plays p ON p.id = pp.play_id WHERE p.owner_id = bgc.member_id('check.member@example.invalid') AND p.bgg_id = 999902 AND p.played_on = '2026-10-21') = 'Check Member:true,Check Pal 2:false'), false));
    res := res || jsonb_build_object('what', 'nobody opens someone else''s play', 'ok', coalesce((NOT (bgc.play_get('nathan.schmidt@curator.invalid', (SELECT id FROM plays WHERE owner_id = bgc.member_id('check.member@example.invalid') AND bgg_id = 999902 AND played_on = '2026-10-21')) ->> 'ok')::boolean), false));
