    res := res || jsonb_build_object('what', 'someone with no plays can', 'ok', coalesce(((bgc.person_remove('check.member@example.invalid', (SELECT legacy_id FROM players WHERE owner_id = bgc.member_id('check.member@example.invalid') AND name = 'Check Pal')) ->> 'ok')::boolean), false));
