    res := res || jsonb_build_object('what', 'remove a place', 'ok', coalesce((NOT (bgc.place_save('check.member@example.invalid', '{"action": "remove", "name": "check library"}') -> 'places') @> '[{"name": "Check Library"}]'), false));
    UPDATE bgg_outbox SET state = 'done' WHERE member_id = bgc.member_id('check.member@example.invalid') AND kind = 'play' AND state = 'pending';
    res := res || jsonb_build_object('what', 'collection sync can be switched off', 'ok', coalesce(((bgc.bgg_link_settings('check.member@example.invalid', '{"collection": false}') -> 'link' ->> 'collection') = 'false'), false));
    res := res || jsonb_build_object('what', 'switching it off drops what was waiting under it', 'ok', coalesce((NOT EXISTS (SELECT 1 FROM bgg_outbox WHERE member_id = bgc.member_id('check.member@example.invalid') AND state = 'pending')), false));
    res := res || jsonb_build_object('what', 'wish for a game', 'ok', coalesce(((bgc.wish_change('check.member@example.invalid', 'add', 999901, 'Check BGG Game', NULL) ->> 'ok')::boolean), false));
    res := res || jsonb_build_object('what', 'with collection sync off, a wish stays here', 'ok', coalesce((NOT EXISTS (SELECT 1 FROM bgg_outbox WHERE member_id = bgc.member_id('check.member@example.invalid') AND state = 'pending')), false));
    res := res || jsonb_build_object('what', 'unlink BGG', 'ok', coalesce(((bgc.bgg_link_remove('check.member@example.invalid') -> 'link' ->> 'linked') = 'false'), false));
    res := res || jsonb_build_object('what', 'unlinking forgets the token and what was waiting', 'ok', coalesce((NOT EXISTS (SELECT 1 FROM bgg_outbox WHERE member_id = bgc.member_id('check.member@example.invalid') AND state = 'pending')), false));
