  EXCEPTION WHEN raise_exception THEN
    IF SQLERRM <> 'self-check done' THEN res := res || jsonb_build_object('what', 'the checks crashed: ' || SQLERRM, 'ok', false); END IF;
  END;
  RETURN res;
END $$;

